using UnityEngine;
using Flynn.Events;

/// <summary>
/// Wrench grapple with swing physics. Hold Q to charge, release to fire.
/// A hook projectile travels from the player's visual center to the target,
/// then the player swings on the rope with pendulum physics (momentum preservation
/// on release). Grapples what the cursor is over (resolved by PlayerMouseAimer):
///   - RopeAnchor → swing the player around the anchor point
///   - RopePullable → reel the object toward the player
/// Blocked while on mud. Requires the wrench as the active item.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer; enabled only while grappling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private TerrainStateAggregator _terrainState;
    private Rigidbody _rb;

    // ── Charge ──────────────────────────────────────────────────────────────

    private float _chargeTimer;
    private bool _charging;

    // ── State machine ───────────────────────────────────────────────────────

    private enum GrappleState { Idle, Firing, Swinging, PullingObject }
    private GrappleState _state = GrappleState.Idle;

    // Firing state
    private Vector3 _fireStart;
    private Vector3 _fireTarget;
    private float _fireElapsed;

    // Swing state
    private Vector3 _anchorPoint;
    private float _ropeLength;
    private float _swingElapsed;

    // Pull state
    private Rigidbody _pullBody;
    private float _pullElapsed;

    // Rope visual
    private const int RopeSegments = 10;
    private Vector3[] _ropePoints;

    // Cached for end-event publishing
    private RopeAnchor _activeAnchor;
    private RopePullable _activePullable;

    // Actual world-space anchor (for visual), separate from the Y-projected _anchorPoint
    private Vector3 _anchorWorldPos;

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime) : 0f;
    public bool IsPulling => _state == GrappleState.Swinging || _state == GrappleState.PullingObject;
    public bool IsSwinging => _state == GrappleState.Swinging;

    /// <summary>
    /// Billboard visual centre — the rope leaves from the sprite's centre, not the feet.
    /// Uses the IPlayerVisual.VisualCenter which accounts for camera-tilt offset on
    /// the billboarded sprite.
    /// </summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    // ── Awake ───────────────────────────────────────────────────────────────

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _terrainState = GetComponent<TerrainStateAggregator>();
        _rb         = GetComponent<Rigidbody>();

        _ropePoints = new Vector3[RopeSegments];

        if (_ropeLine != null)
        {
            _ropeLine.positionCount = RopeSegments;
            _ropeLine.enabled = false;
        }
    }

    // ── Update: input, charging, firing progress ────────────────────────────

    private void Update()
    {
        switch (_state)
        {
            case GrappleState.Idle:
                UpdateIdle();
                break;
            case GrappleState.Firing:
                UpdateFiring();
                break;
            case GrappleState.Swinging:
                UpdateSwingInput();
                break;
            case GrappleState.PullingObject:
                UpdatePullInput();
                break;
        }
    }

    private void UpdateIdle()
    {
        bool onMud = _terrainState != null
            ? _terrainState.CurrentTerrainState.BlocksRope
            : (_controller != null && !_controller.CanJump);
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !onMud;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void UpdateFiring()
    {
        _fireElapsed += Time.deltaTime;
        float fireDuration = _config != null ? _config.hookTravelTime : 0.12f;
        float t = Mathf.Clamp01(_fireElapsed / fireDuration);

        // Ease-out for a snappy travel feel
        float easedT = 1f - Mathf.Pow(1f - t, 3f);
        Vector3 hookPos = Vector3.Lerp(_fireStart, _fireTarget, easedT);

        // Draw extending rope from hand to hook tip (sag fades as hook approaches target)
        DrawRope(HandPoint, hookPos, slack: 0.4f * (1f - t));

        if (t >= 1f)
        {
            if (_activePullable != null)
                StartPullingObject();
            else
                StartSwinging();
        }
    }

    private void UpdateSwingInput()
    {
        // Release with Jump or Q
        if (Input.GetButtonDown("Jump") || Input.GetKeyDown(KeyCode.Q))
        {
            EndGrapple(preserveMomentum: true);
            return;
        }

        // Adjust rope length with scroll wheel
        if (_config != null)
        {
            float scroll = Input.mouseScrollDelta.y;
            if (scroll != 0f)
            {
                _ropeLength -= scroll * _config.ropeAdjustSpeed * Time.deltaTime;
                _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);
            }
        }
    }

    private void UpdatePullInput()
    {
        // Release pull with Q
        if (Input.GetKeyUp(KeyCode.Q))
            EndGrapple(preserveMomentum: false);
    }

    // ── Fire ────────────────────────────────────────────────────────────────

    private void FireLasso()
    {
        if (_config == null) return;

        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(HandPoint, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        // Battery check
        var battery = RobotBattery.Instance;
        float grappleCost = battery != null && battery.Settings != null
            ? battery.Settings.grappleCost : 0f;
        if (battery != null && !battery.CanSpend(grappleCost)) return;
        if (battery != null && grappleCost > 0f) battery.Spend(grappleCost);

        // Cache targets for events
        _activeAnchor = anchor;
        _activePullable = pullable;

        // Start firing
        _state = GrappleState.Firing;
        _fireStart = HandPoint;
        _fireTarget = grapplePoint;
        _fireElapsed = 0f;

        // Face the target
        if (_animDriver != null) _animDriver.FaceWorldDirection(grapplePoint - transform.position);

        // Publish start event immediately
        if (GameEventBus.Instance != null)
        {
            if (pullable != null)
                GameEventBus.Instance.Publish(new RopePullStarted(pullable));
            else if (anchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleStarted(anchor));
        }
    }

    // ── State transitions ───────────────────────────────────────────────────

    private void StartSwinging()
    {
        _state = GrappleState.Swinging;
        _swingElapsed = 0f;

        // 2.5D: project the anchor onto the player's Y so the tether is horizontal-only.
        // The rope constrains on the XZ plane; Y is entirely gravity/jump controlled.
        _anchorPoint = new Vector3(_fireTarget.x, _rb.position.y, _fireTarget.z);
        _anchorWorldPos = _fireTarget;

        // Rope length = initial horizontal distance to anchor
        Vector3 toAnchorXZ = _anchorPoint - _rb.position;
        toAnchorXZ.y = 0f;
        _ropeLength = toAnchorXZ.magnitude;
        if (_config != null)
            _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);

        // Snap impulse toward anchor on XZ only (no vertical yank)
        if (_config != null && _config.snapForce > 0f && _rb != null)
        {
            Vector3 toAnchor = (_anchorPoint - _rb.position);
            toAnchor.y = 0f;
            if (toAnchor.sqrMagnitude > 0.01f)
                _rb.AddForce(toAnchor.normalized * _config.snapForce, ForceMode.Impulse);
        }

        // Suppress character controller so it doesn't fight the swing
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void StartPullingObject()
    {
        _state = GrappleState.PullingObject;
        _pullBody = _activePullable != null ? _activePullable.Body : null;
        _pullElapsed = 0f;

        if (_pullBody == null) { EndGrapple(false); return; }
    }

    // ── FixedUpdate: swing & pull physics ────────────────────────────────────

    private void FixedUpdate()
    {
        switch (_state)
        {
            case GrappleState.Swinging:
                UpdateSwingPhysics();
                break;
            case GrappleState.PullingObject:
                UpdatePullPhysics();
                break;
        }
    }

    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
            EndGrapple(true);
            return;
        }

        // Battery drain while swinging
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(true); return; }
        }

        // 2.5D: re-project anchor to player's Y each step so the tether stays horizontal
        // even as the player rises/falls from gravity and jumps.
        _anchorPoint = new Vector3(_anchorPoint.x, _rb.position.y, _anchorPoint.z);

        // Swing input: WASD adds tangential force on the XZ plane to pump the swing
        Vector3 inputDir = new Vector3(
            Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
        if (inputDir.sqrMagnitude > 0.01f)
        {
            Vector3 toAnchorXZ = (_anchorPoint - _rb.position);
            toAnchorXZ.y = 0f;
            if (toAnchorXZ.sqrMagnitude > 0.001f)
            {
                toAnchorXZ.Normalize();
                // Tangent on XZ: perpendicular to the rope direction
                Vector3 tangent = inputDir - Vector3.Project(inputDir, toAnchorXZ);
                tangent.y = 0f;
                if (tangent.sqrMagnitude > 0.001f)
                {
                    tangent.Normalize();
                    float swingForce = _config != null ? _config.swingForce : 30f;
                    _rb.AddForce(tangent * swingForce, ForceMode.Acceleration);
                }
            }
        }

        // 2.5D: enforce rope length constraint on the XZ plane only.
        // Y is untouched — gravity and jumps work normally while tethered.
        Vector3 toAnchorVec = _anchorPoint - _rb.position;
        toAnchorVec.y = 0f;
        float currentDistXZ = toAnchorVec.magnitude;

        if (currentDistXZ > _ropeLength && currentDistXZ > 0.001f)
        {
            Vector3 dirXZ = toAnchorVec.normalized;

            // Correct XZ position to stay on the horizontal rope circle
            Vector3 corrected = _rb.position;
            corrected.x = _anchorPoint.x - dirXZ.x * _ropeLength;
            corrected.z = _anchorPoint.z - dirXZ.z * _ropeLength;
            _rb.position = corrected;

            // Remove outward radial XZ velocity (keep tangential + all Y velocity)
            Vector3 outwardXZ = new Vector3(-dirXZ.x, 0f, -dirXZ.z);
            float vOut = Vector3.Dot(new Vector3(_rb.velocity.x, 0f, _rb.velocity.z), outwardXZ);
            if (vOut > 0f)
            {
                Vector3 correction = outwardXZ * vOut;
                _rb.velocity -= correction;
            }

            // Cap XZ swing speed only (Y is free)
            Vector3 velXZ = new Vector3(_rb.velocity.x, 0f, _rb.velocity.z);
            if (_config != null && velXZ.magnitude > _config.maxSwingSpeed)
            {
                velXZ = velXZ.normalized * _config.maxSwingSpeed;
                _rb.velocity = new Vector3(velXZ.x, _rb.velocity.y, velXZ.z);
            }
        }

        // Suppress character controller each step (it auto-resets to 1)
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void UpdatePullPhysics()
    {
        if (_pullBody == null) { EndGrapple(false); return; }

        _pullElapsed += Time.fixedDeltaTime;
        if (_config != null && _pullElapsed >= _config.pullTimeout)
        {
            EndGrapple(false);
            return;
        }

        // Battery drain while pulling
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(false); return; }
        }

        // Pull the object toward the player's hand
        Vector3 target = HandPoint;
        Vector3 to = target - _pullBody.position;

        float stopRadius = _config != null ? _config.stopRadius : 0.8f;
        if (to.magnitude <= stopRadius)
        {
            EndGrapple(false);
            return;
        }

        float pullForce = _config != null ? _config.pullForce : 55f;
        float maxPullSpeed = _config != null ? _config.maxPullSpeed : 14f;

        _pullBody.AddForce(to.normalized * pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * maxPullSpeed;
    }

    // ── End grapple ─────────────────────────────────────────────────────────

    private void EndGrapple(bool preserveMomentum)
    {
        // Publish end events
        if (GameEventBus.Instance != null)
        {
            if (_activeAnchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleEnded(_activeAnchor));
            if (_activePullable != null)
                GameEventBus.Instance.Publish(new RopePullEnded(_activePullable));
        }

        // 2.5D: on swing release, just let momentum carry — no forced vertical boost.
        // The player keeps their current XZ swing velocity (tangential) plus whatever
        // Y velocity they have from gravity/jumps.

        // Restore character controller
        if (_controller != null) _controller.SteeringControl = 1f;

        _state = GrappleState.Idle;
        _pullBody = null;
        _swingElapsed = 0f;
        _pullElapsed = 0f;
        _activeAnchor = null;
        _activePullable = null;
    }

    // ── LateUpdate: rope visual ─────────────────────────────────────────────

    private void LateUpdate()
    {
        if (_ropeLine == null) return;

        switch (_state)
        {
            case GrappleState.Swinging:
                // Taut rope from hand to the actual world anchor (not Y-projected)
                DrawRope(HandPoint, _anchorWorldPos, slack: 0.02f);
                break;

            case GrappleState.PullingObject:
                if (_pullBody != null)
                    DrawRope(HandPoint, _pullBody.position, slack: 0.08f);
                else
                    _ropeLine.enabled = false;
                break;

            case GrappleState.Firing:
                // Handled in UpdateFiring
                break;

            default:
                _ropeLine.enabled = false;
                break;
        }
    }

    // ── Rope drawing with sag ───────────────────────────────────────────────

    /// <summary>
    /// Draw the rope from start to end with a parabolic sag.
    /// slack=0 → taut straight line; slack=0.3 → visible droop.
    /// </summary>
    private void DrawRope(Vector3 start, Vector3 end, float slack)
    {
        if (_ropeLine == null) return;

        _ropeLine.enabled = true;

        float dist = Vector3.Distance(start, end);

        for (int i = 0; i < RopeSegments; i++)
        {
            float t = (float)i / (RopeSegments - 1);
            Vector3 point = Vector3.Lerp(start, end, t);

            // Parabolic sag: max at middle, zero at ends
            float sagAmount = slack * 4f * t * (1f - t) * dist;
            point += Vector3.down * sagAmount;

            _ropePoints[i] = point;
        }

        _ropeLine.SetPositions(_ropePoints);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Pulls an auto-collecting <see cref="WorldItem"/> to the player after a short settle delay, then
/// collects it: resources/items go to the inventory, currencies to their counter. If the inventory
/// has no room the item idles on the ground and re-checks periodically (VS-style gem behaviour).
///
/// Finds the player through a <see cref="PlayerAnchor"/> SO — no FindObjectOfType. Non-auto items
/// (the wrench) disable this component and are picked up with the pickup key instead.
/// </summary>
[RequireComponent(typeof(WorldItem))]
public class DroppedItemMagnet : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _playerAnchor;

    [Header("Timing")]
    [Tooltip("Seconds the drop sits/settles before it may fly to the player.")]
    [SerializeField] private float _settleDelay = 0.6f;
    [Tooltip("How often to re-check for inventory room while waiting.")]
    [SerializeField] private float _roomRecheckInterval = 0.4f;

    [Header("Flight")]
    [SerializeField] private float _maxSpeed = 7f;
    [SerializeField] private float _acceleration = 16f;
    [SerializeField] private float _collectRadius = 0.55f;
    [SerializeField] private float _targetHeight = 0.6f;

    private WorldItem _item;
    private Rigidbody _rb;

    private float _age;
    private float _extraDelay;
    private float _recheckTimer;
    private float _speed;
    private bool _flying;

    /// <summary>
    /// Delay auto-collection by <paramref name="seconds"/> beyond the normal settle (used when the
    /// player drops an item so it doesn't instantly fly back). Takes the longer of any pending delay.
    /// </summary>
    public void Suppress(float seconds)
    {
        _extraDelay = Mathf.Max(_extraDelay, seconds);
        _flying = false;
    }

    private void Awake()
    {
        _item = GetComponent<WorldItem>();
        _rb = GetComponent<Rigidbody>();
    }

    private void OnEnable()
    {
        _age = 0f;
        _extraDelay = 0f;
        _recheckTimer = 0f;
        _speed = 0f;
        _flying = false;
    }

    private void Update()
    {
        ItemDefinition def = _item != null ? _item.Item : null;
        if (def == null) return;

        // Non-auto items (wrench) wait for the pickup key — not our job.
        if (!def.AutoCollects) { enabled = false; return; }

        _age += Time.deltaTime;
        if (_age < _settleDelay + _extraDelay) return;

        Transform player = _playerAnchor != null ? _playerAnchor.Current : null;
        if (player == null) return;

        if (!_flying)
        {
            _recheckTimer -= Time.deltaTime;
            if (_recheckTimer > 0f) return;
            _recheckTimer = _roomRecheckInterval;
            if (!HasRoom(def, player)) return;
            BeginFlight();
        }

        _speed = Mathf.MoveTowards(_speed, _maxSpeed, _acceleration * Time.deltaTime);
        Vector3 target = player.position + Vector3.up * _targetHeight;
        transform.position = Vector3.MoveTowards(transform.position, target, _speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) <= _collectRadius)
            Collect(def, player);
    }

    private bool HasRoom(ItemDefinition def, Transform player)
    {
        if (def.isCurrency) return true;
        return PlayerInventory.Instance != null && PlayerInventory.Instance.HasRoomFor(def);
    }

    private void BeginFlight()
    {
        _flying = true;
        if (_rb != null)
        {
            _rb.velocity = Vector3.zero;
            _rb.angularVelocity = Vector3.zero;
            _rb.isKinematic = true; // hand control to the magnet's MoveTowards
        }
    }

    private void Collect(ItemDefinition def, Transform player)
    {
        if (def.isCurrency)
        {
            if (def.currencyTarget != null) def.currencyTarget.Add(_item.Count);
            if (GameEventBus.Instance != null)
                GameEventBus.Instance.Publish(new CurrencyCollected(def, _item.Count));
            Destroy(gameObject);
            return;
        }

        int added = PlayerInventory.Instance != null ? PlayerInventory.Instance.TryAddItem(def, _item.Count) : 0;
        if (added >= _item.Count)
        {
            Destroy(gameObject);
            return;
        }

        // Inventory filled mid-flight: drop the remainder back on the ground and idle.
        if (added > 0) _item.Reduce(added);
        _flying = false;
        _speed = 0f;
        if (_rb != null) _rb.isKinematic = false;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Picks up the key-pickup <see cref="WorldItem"/> the player is aiming at when the pickup key is
/// pressed: grants its item(s) to the inventory and removes it from the world. Only non-auto-collect
/// items (e.g. the wrench) need this — auto-collect drops fly to the player on their own.
/// Reads the hovered item from <see cref="PlayerMouseAimer"/>; writes to <see cref="PlayerInventory"/>.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerPickupController : MonoBehaviour
{
    [SerializeField] private KeyCode _pickupKey = KeyCode.E;

    private PlayerMouseAimer _aimer;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_pickupKey)) return;

        WorldItem item = _aimer.HoveredKeyPickup;
        if (item == null || item.Item == null) return;

        PlayerInventory inv = PlayerInventory.Instance;
        if (inv == null) return;

        int added = inv.TryAddItem(item.Item, item.Count);
        if (added <= 0) return;

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemPickedUp(item.Item, added));

        if (added >= item.Count) Destroy(item.gameObject);
        else                     item.Reduce(added);
    }
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    [Tooltip("Max distance from the player to a resource or pickup for it to count as interactable.")]
    [SerializeField] private float _interactionRange = 3f;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    /// <summary>
    /// Unified hover result produced each frame. All consumers should read from this
    /// instead of the individual HoveredXxx properties (which are deprecated).
    /// </summary>
    public PlayerAimHoverResult HoverResult { get; private set; }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);

        // Build unified hover result
        BuildHoverResult(hasHit, point, hovered);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;

    private void BuildHoverResult(bool hasHit, Vector3 point, GameObject hovered)
    {
        HoverResult = new PlayerAimHoverResult
        {
            HasTarget = hasHit || HoveredAnchor != null || HoveredPullable != null,
            WorldPoint = WorldAimPoint,
            WorldItem = HoveredKeyPickup,
            ResourceNode = HoveredResource,
            MeleeResource = MeleeResource,
            RopeAnchor = HoveredAnchor,
            RopePullable = HoveredPullable,
            ScanTarget = hovered != null ? Find<ScanTarget>(hovered) : null,
            Interactable = HoveredInteractable,
            GrapplePoint = HoveredGrapplePoint,
            InInteractionRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange,
            InMeleeRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _meleeRange,
            SwingAnimIndex = SwingAnimIndex,
        };
    }
}

using UnityEngine;

/// <summary>
/// Drives the procedural cube character rig (twin-stick). Replaces the sprite-sheet
/// <see cref="FlynnAnimationDriver"/> on the cube player while satisfying the same
/// <see cref="IPlayerVisual"/> contract, so wrench/throw/rope/reticle keep working.
///
/// Rig layout (assigned in the Inspector):
///   BodyRig  — yaws to follow the mouse aim point (torso + arms).
///   LegRig   — yaws to the movement direction when moving, blends back to body when idle.
///   FootL/R  — translated in an opposite-phase step cycle along LegRig's local forward.
///   ArmR     — pitched back on charge, swept forward on release (procedural swing pose).
///
/// Decoupling BodyRig (→ mouse) from LegRig (→ move) is what produces the twin-stick look:
/// the torso aims while the legs walk in the direction you actually travel.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class ProceduralCharacterDriver : MonoBehaviour, IPlayerVisual
{
    [Header("Sources")]
    [SerializeField] private SolarpunkCharacterController _controller;

    [Header("Rig")]
    [Tooltip("Torso pivot. Yaws to face the mouse aim point. Holds the body cube + arms.")]
    [SerializeField] private Transform _bodyRig;
    [Tooltip("Leg pivot. Yaws to the movement direction; blends to body facing when idle.")]
    [SerializeField] private Transform _legRig;
    [SerializeField] private Transform _footL;
    [SerializeField] private Transform _footR;
    [Tooltip("Right arm, swept procedurally during a swing.")]
    [SerializeField] private Transform _armR;
    [Tooltip("Hand position used as the throw/rope origin (VisualCenter). Falls back to body centre.")]
    [SerializeField] private Transform _handSocket;

    [Header("Facing")]
    [Tooltip("Rest / idle facing in world space (default -Z = toward the camera / screen-down).")]
    [SerializeField] private Vector3 _restForward = Vector3.back;
    [Tooltip("How far the body turns toward the movement heading off the rest facing. " +
             "1 = face the move direction fully (up = away from camera); " +
             "lower softens it (0.5 → pure left/right leans ~45°). Idle always returns to rest.")]
    [SerializeField, Range(0f, 1f)] private float _leanFactor = 1f;
    [Tooltip("How fast the body/legs slerp toward their target facing (per second).")]
    [SerializeField] private float _turnSpeed = 14f;

    [Header("Step cycle")]
    [Tooltip("Stride length: how far each foot travels fore/aft from neutral (world units).")]
    [SerializeField] private float _stride = 0.12f;
    [Tooltip("Foot lift height at the top of a step (world units).")]
    [SerializeField] private float _stepLift = 0.06f;
    [Tooltip("Step cycles per second at full speed.")]
    [SerializeField] private float _stepFrequency = 2.2f;

    [Header("Visual centre")]
    [Tooltip("Used only when no hand socket is assigned: body-centre height above the root.")]
    [SerializeField] private float _visualHalfHeight = 0.4f;

    [Header("Swing pose")]
    [Tooltip("Arm pitch (deg, local X) at full windup charge.")]
    [SerializeField] private float _windupAngle = -70f;
    [Tooltip("Arm pitch (deg, local X) at the forward end of a swing.")]
    [SerializeField] private float _swingThroughAngle = 60f;
    [Tooltip("Seconds the release sweep takes.")]
    [SerializeField] private float _swingDuration = 0.25f;

    private const float MoveEpsilon = 0.05f;

    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private float _chargePitch;       // current windup pitch while charging
    private float _swingTimer;        // counts down through the release sweep
    private Quaternion _armRest = Quaternion.identity;

    private Vector3 _footLRest;
    private Vector3 _footRRest;
    private float _stepPhase;
    private float _stepWeight;        // 0 idle → 1 moving, smoothed so feet settle

    // ── IPlayerVisual ───────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _handSocket != null ? _handSocket.position
                            : transform.position + Vector3.up * _visualHalfHeight;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking => _swingPhase != SwingPhase.None;

    public void TriggerAttack(int animIndex)
    {
        // No charge: snap straight into a release sweep.
        if (_swingPhase == SwingPhase.None) ReleaseSwing(animIndex, 1f);
    }

    public void BeginChargePose(int animIndex)
    {
        _swingPhase = SwingPhase.Charging;
        _chargePitch = 0f;
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        if (_swingPhase != SwingPhase.Charging) return;
        _chargePitch = Mathf.Lerp(0f, _windupAngle, Mathf.Clamp01(charge01));
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        _swingPhase = SwingPhase.Releasing;
        // Higher animSpeed → shorter sweep (faster follow-through).
        _swingTimer = _swingDuration / Mathf.Max(0.05f, animSpeed);
    }

    public void CancelSwing()
    {
        _swingPhase = SwingPhase.None;
        _swingTimer = 0f;
        _chargePitch = 0f;
    }

    public void FaceWorldDirection(Vector3 worldDir)
    {
        // No-op: facing is fully movement-driven (lean-to-move). Kept for the IPlayerVisual
        // contract — the wrench/rope controllers still call it, but it must not fight the lean.
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private float _restYaw;

    private void Awake()
    {
        if (_controller == null) _controller = GetComponent<SolarpunkCharacterController>();
        Vector3 rest = _restForward; rest.y = 0f;
        if (rest.sqrMagnitude < 0.0001f) rest = Vector3.back;
        _restYaw = Quaternion.LookRotation(rest.normalized, Vector3.up).eulerAngles.y;
        if (_footL != null) _footLRest = _footL.localPosition;
        if (_footR != null) _footRRest = _footR.localPosition;
        if (_armR != null) _armRest = _armR.localRotation;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        UpdateBodyFacing(dt);
        UpdateLegFacing(dt);
        UpdateStepCycle(dt);
        UpdateSwingPose(dt);
    }

    // ── Rig logic ───────────────────────────────────────────────────────────────

    private void UpdateBodyFacing(float dt)
    {
        if (_bodyRig == null) return;

        Vector3 move = _controller.MoveInput;
        move.y = 0f;

        // Turn toward the movement heading in all directions (up = facing away from camera).
        // _leanFactor scales how much of the rest→move angular delta is applied; 1 = face the
        // move direction fully. Idle → rest facing.
        float targetYaw = _restYaw;
        if (move.sqrMagnitude > MoveEpsilon * MoveEpsilon)
        {
            float moveYaw = Quaternion.LookRotation(move.normalized, Vector3.up).eulerAngles.y;
            targetYaw = _restYaw + Mathf.DeltaAngle(_restYaw, moveYaw) * _leanFactor;
        }

        Quaternion target = Quaternion.Euler(0f, targetYaw, 0f);
        _bodyRig.rotation = Quaternion.Slerp(_bodyRig.rotation, target, _turnSpeed * dt);
    }

    private void UpdateLegFacing(float dt)
    {
        // Legs share the body facing; the step cycle runs along that shared forward.
        if (_legRig != null && _bodyRig != null) _legRig.rotation = _bodyRig.rotation;
    }

    private void UpdateStepCycle(float dt)
    {
        float speed01 = Mathf.Clamp01(_controller != null ? _controller.NormalizedSpeed : 0f);
        bool moving = speed01 > 0.05f;

        // Ease the step amplitude in/out so feet settle cleanly when stopping.
        _stepWeight = Mathf.MoveTowards(_stepWeight, moving ? 1f : 0f, dt * 6f);
        if (moving) _stepPhase += dt * _stepFrequency * Mathf.Lerp(0.4f, 1f, speed01) * Mathf.PI * 2f;

        float s = Mathf.Sin(_stepPhase) * _stepWeight;
        ApplyFoot(_footL, _footLRest, s);
        ApplyFoot(_footR, _footRRest, -s);
    }

    private void ApplyFoot(Transform foot, Vector3 rest, float phase)
    {
        if (foot == null) return;
        // phase ∈ [-1,1]: fore/aft along local Z, lift only on the forward (positive) half.
        foot.localPosition = rest
            + Vector3.forward * (phase * _stride)
            + Vector3.up * (Mathf.Max(0f, phase) * _stepLift);
    }

    private void UpdateSwingPose(float dt)
    {
        if (_armR == null) return;

        float pitch;
        switch (_swingPhase)
        {
            case SwingPhase.Charging:
                pitch = _chargePitch;
                break;
            case SwingPhase.Releasing:
                _swingTimer -= dt;
                float t = _swingDuration > 0f
                    ? 1f - Mathf.Clamp01(_swingTimer / (_swingDuration))
                    : 1f;
                // Sweep from the windup angle through to the follow-through angle.
                pitch = Mathf.Lerp(_windupAngle, _swingThroughAngle, t);
                if (_swingTimer <= 0f) _swingPhase = SwingPhase.None;
                break;
            default:
                pitch = 0f;
                break;
        }

        Quaternion target = _armRest * Quaternion.Euler(pitch, 0f, 0f);
        // Snap while actively swinging, ease back to rest when idle.
        _armR.localRotation = _swingPhase == SwingPhase.None
            ? Quaternion.Slerp(_armR.localRotation, target, 12f * dt)
            : target;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }

        if (GameEventBus.Instance != null)
            GameEventBus.Instance.Publish(new ItemDropped(item, count, pos));
    }
}

